SET PAGESIZE 0
SET FEEDBACK OFF
SET HEADING OFF
SET LINESIZE 4000
SET TRIMSPOOL ON
PROMPT ==== SESSION ====
SELECT 'DB|'||USER||'|'||SYS_CONTEXT('USERENV','DB_NAME')||'|'||TO_CHAR(SYSTIMESTAMP,'YYYY-MM-DD HH24:MI:SS') FROM DUAL;
